{"cmd":"node <<'NODE'
const fs = require('fs');
const cp = require('child_process');
const data = JSON.parse(fs.readFileSync('/usr/share/iso-codes/json/iso_4217.json', 'utf8'))['4217'];
const codes = [...new Set(data.map((item) => item.alpha_3))].sort();
const results = [];
for (const code of codes) {
  try {
    const output = cp.execFileSync('/workspace/dataset/test19_executable', ['--amount1', '1.2345', '--amount2', '9', '--currency', code], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trimEnd();
    const parts = output.split('\u00a0');
    if (parts.length !== 2) {
      results.push({ code, error: `unexpected:${JSON.stringify(output)}` });
      continue;
    }
    const prefix = parts[0];
    const amount = parts[1];
    const digits = amount.includes('.') ? amount.split('.')[1].length : 0;
    results.push({ code, prefix, digits });
  } catch (error) {
    const stderr = error.stderr ? String(error.stderr) : '';
    const message = stderr.split('\n').find((line) => line.includes('CurrencyDoesNotExist')) || stderr.split('\n').find(Boolean) || error.message;
    results.push({ code, error: message });
  }
}
console.log(JSON.stringify(results, null, 2));
NODE","yield_time_ms":1000,"max_output_tokens":40000}

