      if (token.startsWith('-h=')) {
        throw buildArgumentError(
          scriptName,
          optionDefinitions,
          `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
        );
      }

      throw new CliExit(0, formatHelp(scriptName, optionDefinitions));
    }

    if (!token.startsWith('--') || token.length === 2) {
      extras.push(token);
      continue;
    }

    const equalsIndex = token.indexOf('=');
    const rawOptionName = token.slice(2, equalsIndex === -1 ? undefined : equalsIndex);
    const explicitValue = equalsIndex === -1 ? null : token.slice(equalsIndex + 1);
    const resolution = resolveLongOption(rawOptionName, optionDefinitions);

    if (resolution.kind === 'ambiguous') {
      throw buildArgumentError(
        scriptName,
        optionDefinitions,
        `ambiguous option: --${rawOptionName} could match ${resolution.matches.map((match) => `--${match}`).join(', ')}`,
      );
    }

    if (resolution.kind === 'unknown') {
      extras.push(token);
      continue;
    }

    if (resolution.kind === 'help') {
      if (explicitValue !== null) {
        throw buildArgumentError(
          scriptName,
          optionDefinitions,
          `argument -h/--help: ignored explicit argument '${explicitValue}'`,
        );
      }

      throw new CliExit(0, formatHelp(scriptName, optionDefinitions));
    }

    const option = resolution.option;
    let rawValue = explicitValue;

    if (rawValue === null) {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || looksLikeMissingValue(nextToken)) {
        throw buildArgumentError(
          scriptName,
          optionDefinitions,
          `argument --${option.longName}: expected one argument`,
        );
      }

      rawValue = nextToken;
      index += 1;
    }

    try {
      parsedValues[option.longName] = option.parse(rawValue);
    } catch {
      throw buildArgumentError(
        scriptName,
        optionDefinitions,
        `argument --${option.longName}: invalid ${option.typeLabel} value: '${rawValue}'`,
      );
    }
  }

  const missingRequired = optionDefinitions
    .filter((option) => option.required && !(option.longName in parsedValues))
    .map((option) => `--${option.longName}`);

  if (missingRequired.length > 0) {
    throw buildArgumentError(
      scriptName,
      optionDefinitions,
      `the following arguments are required: ${missingRequired.join(', ')}`,
    );
  }

  if (extras.length > 0) {
    throw buildArgumentError(
      scriptName,
      optionDefinitions,
      `unrecognized arguments: ${extras.join(' ')}`,
    );
  }

  return parsedValues;
}

function resolveLongOption(rawOptionName, optionDefinitions) {
  if (rawOptionName === HELP_LONG) {
    return { kind: 'help' };
  }

  const exactMatch = optionDefinitions.find((option) => option.longName === rawOptionName);
  if (exactMatch) {
    return { kind: 'option', option: exactMatch };
  }

  const candidateNames = [HELP_LONG, ...optionDefinitions.map((option) => option.longName)];
  const prefixMatches = candidateNames.filter((name) => name.startsWith(rawOptionName));

  if (prefixMatches.length === 0) {
    return { kind: 'unknown' };
  }

  if (prefixMatches.length > 1) {
    return { kind: 'ambiguous', matches: prefixMatches };
  }

  if (prefixMatches[0] === HELP_LONG) {
    return { kind: 'help' };
  }

  return {
    kind: 'option',
    option: optionDefinitions.find((option) => option.longName === prefixMatches[0]),
  };
}

function looksLikeMissingValue(token) {
  return token.startsWith('-') && !NEGATIVE_NUMBER_PATTERN.test(token);
}

function buildArgumentError(scriptName, optionDefinitions, message) {
  return new CliExit(
    2,
    `${formatUsage(scriptName, optionDefinitions)}\n${scriptName}: error: ${message}\n`,
  );
}

function formatHelp(scriptName, optionDefinitions) {
  const lines = [
    formatUsage(scriptName, optionDefinitions),
    '',
    'options:',
    `  -${HELP_SHORT}, --${HELP_LONG}           ${HELP_TEXT}`,
    ...optionDefinitions.map((option) => `  --${option.longName} ${option.valueName}`),
  ];

  return `${lines.join('\n')}\n`;
}

function formatUsage(scriptName, optionDefinitions) {
  const initialPrefix = `usage: ${scriptName}`;
  const continuationPrefix = ' '.repeat(`usage: ${scriptName} `.length);
  const usageTokens = ['[-h]'];

  for (const option of optionDefinitions) {
    usageTokens.push(`--${option.longName}`);
    usageTokens.push(option.valueName);
  }

  const lines = [];
  let currentLine = initialPrefix;

  for (const token of usageTokens) {
    const candidate = `${currentLine} ${token}`;
    if (candidate.length <= MAX_USAGE_WIDTH) {
      currentLine = candidate;
      continue;
    }

    lines.push(currentLine);
    currentLine = `${continuationPrefix}${token}`;
  }

  lines.push(currentLine);
  return lines.join('\n');
}

function basename(scriptPath) {
  if (!scriptPath) {
    return 'test19.mjs';
  }

  const normalized = scriptPath.replace(/\\/g, '/');
  const lastSlashIndex = normalized.lastIndexOf('/');
  return lastSlashIndex === -1 ? normalized : normalized.slice(lastSlashIndex + 1);
}

