const NBSP = '\u00A0';

export function formatMoneyString(amount, currency) {
  const negative = amount < 0 || Object.is(amount, -0);
  const magnitude = formatMagnitude(amount, currency.fractionDigits);
  return `${negative ? '-' : ''}${currency.prefix}${NBSP}${magnitude}`;
}

function formatMagnitude(amount, fractionDigits) {
  if (Number.isNaN(amount)) {
    return 'NaN';
  }

  if (!Number.isFinite(amount)) {
    return 'INF';
  }

  return roundHalfEven(toPlainDecimalString(Math.abs(amount)), fractionDigits);
}

function toPlainDecimalString(value) {
  const raw = String(value);

  if (!/[eE]/.test(raw)) {
    return raw;
  }

  const [coefficient, exponentText] = raw.toLowerCase().split('e');
  const exponent = Number(exponentText);
  const [integerPart, fractionPart = ''] = coefficient.split('.');
  const digits = `${integerPart}${fractionPart}`.replace(/^0+(?=\d)/, '');

  if (digits === '' || /^0+$/.test(digits)) {
    return '0';
  }

  const decimalIndex = integerPart.length + exponent;

  if (decimalIndex <= 0) {
    return `0.${'0'.repeat(-decimalIndex)}${digits}`;
  }

  if (decimalIndex >= digits.length) {
    return `${digits}${'0'.repeat(decimalIndex - digits.length)}`;
  }

  return `${digits.slice(0, decimalIndex)}.${digits.slice(decimalIndex)}`;
}

function roundHalfEven(decimalText, fractionDigits) {
  let [integerPart, fractionPart = ''] = decimalText.split('.');
  integerPart = integerPart.replace(/^0+(?=\d)/, '');

  if (integerPart === '') {
    integerPart = '0';
  }

  if (fractionPart.length <= fractionDigits) {
    if (fractionDigits === 0) {
      return integerPart;
    }

    return `${integerPart}.${fractionPart.padEnd(fractionDigits, '0')}`;
  }

  const keptFraction = fractionPart.slice(0, fractionDigits);
  const nextDigit = fractionPart.charCodeAt(fractionDigits) - 48;
  const remainingDigits = fractionPart.slice(fractionDigits + 1);
  const shouldRoundUp = nextDigit > 5
    || (nextDigit === 5 && (/[1-9]/.test(remainingDigits) || hasOddLastRetainedDigit(integerPart, keptFraction)));

  let combinedDigits = `${integerPart}${keptFraction}`;

  if (shouldRoundUp) {
    combinedDigits = incrementDigitString(combinedDigits);
  }

  if (fractionDigits === 0) {
    return combinedDigits;
  }

  if (combinedDigits.length <= fractionDigits) {
    combinedDigits = combinedDigits.padStart(fractionDigits + 1, '0');
  }

  const roundedIntegerPart = combinedDigits.slice(0, -fractionDigits) || '0';
  const roundedFractionPart = combinedDigits.slice(-fractionDigits);
  return `${roundedIntegerPart}.${roundedFractionPart}`;
}

function hasOddLastRetainedDigit(integerPart, keptFraction) {
  const source = keptFraction.length > 0 ? keptFraction : integerPart;
  const lastDigit = source[source.length - 1] ?? '0';
  return ((lastDigit.charCodeAt(0) - 48) & 1) === 1;
}

function incrementDigitString(digits) {
  const characters = digits.split('');
  let carry = 1;

  for (let index = characters.length - 1; index >= 0 && carry === 1; index -= 1) {
    const digit = characters[index].charCodeAt(0) - 48 + carry;

    if (digit === 10) {
      characters[index] = '0';
      continue;
    }

    characters[index] = String(digit);
    carry = 0;
  }

  if (carry === 1) {
    characters.unshift('1');
  }

  return characters.join('');
}

/output/test19.mjs.content:
import { CliExit } from './lib/cli/argparse_like.mjs';
import { Money } from './lib/money/money.mjs';
import { parseTest19Arguments } from './lib/test19/arguments.mjs';

try {
  const args = parseTest19Arguments(process.argv.slice(2), process.argv[1]);
  const m1 = new Money(args.amount1, args.currency);
  const m2 = new Money(args.amount2, args.currency);
  const smaller = m1.isLessThan(m2) ? m1 : m2;
  process.stdout.write(`${smaller.toString()}\n`);
} catch (error) {
  if (error instanceof CliExit) {
    const stream = error.exitCode === 0 ? process.stdout : process.stderr;
    stream.write(error.output);
    process.exitCode = error.exitCode;
  } else {
    throw error;
  }
}

