import { parseCommandLine, parsePythonFloat } from '../cli/argparse_like.mjs';

const OPTION_DEFINITIONS = Object.freeze([
  {
    longName: 'amount1',
    valueName: 'AMOUNT1',
    required: true,
    parse: parsePythonFloat,
    typeLabel: 'float',
  },
  {
    longName: 'amount2',
    valueName: 'AMOUNT2',
    required: true,
    parse: parsePythonFloat,
    typeLabel: 'float',
  },
  {
    longName: 'currency',
    valueName: 'CURRENCY',
    required: true,
    parse: (value) => value,
    typeLabel: 'str',
  },
]);

export function parseTest19Arguments(argv, scriptPath) {
  return parseCommandLine({
    argv,
    scriptPath,
    optionDefinitions: OPTION_DEFINITIONS,
  });
}

/output/lib/money/money.mjs.content:
import { getCurrencyData } from './currency_data.mjs';
import { formatMoneyString } from './decimal_format.mjs';

export class Money {
  constructor(amount, currencyCode) {
    this.amount = amount;
    this.currency = getCurrencyData(currencyCode);
  }

  isLessThan(other) {
    if (Number.isNaN(this.amount) || Number.isNaN(other.amount)) {
      throw new Error("[<class 'decimal.InvalidOperation'>]");
    }

    return this.amount < other.amount;
  }

  toString() {
    return formatMoneyString(this.amount, this.currency);
  }
}

